      custodians: [{ method: "GET", path: "/v1/custodians" }, { method: "POST", path: "/v1/custodians" }, { method: "GET", path: "/v1/dataset-approvals" }, { method: "POST", path: "/v1/dataset-approvals" }, { method: "GET", path: "/v1/quality-issues" }, { method: "POST", path: "/v1/quality-issues" }],
