      "shadow-ai": [{ method: "GET", path: "/v1/shadow-ai-systems" }, { method: "POST", path: "/v1/shadow-ai-systems" }, { method: "GET", path: "/v1/shadow-ai-systems/:systemId" }, { method: "POST", path: "/v1/shadow-ai-systems/:systemId/remediation" }],
      "talent-assignments": [{ method: "GET", path: "/v1/talent-assignments" }, { method: "POST", path: "/v1/talent-assignments" }, { method: "GET", path: "/v1/talent-assignments/:assignmentId" }],
